package example.bankwealth.generated

import akka.actor.testkit.typed.scaladsl.ActorTestKit
import akka.persistence.testkit.PersistenceTestKitPlugin
import com.typesafe.config.ConfigFactory
import org.scalatest.funsuite.AnyFunSuite

final class GeneratedActorStateSpec extends AnyFunSuite {
  example.bankwealth.infrastructure.bootstrap.UnitConfigurationCheck.main(Array.empty)
  test("bankwealth/CreditBalance real actor serves typed state") {
    val kit = ActorTestKit(ConfigFactory.parseString("akka.actor.provider = local").withFallback(PersistenceTestKitPlugin.config).withFallback(ConfigFactory.load()))
    try {
      val hosts = new example.bankwealth.domain.services.CreditBalanceComputations {
        def BalanceAfterCommitIncomingCredits(state: example.bankwealth.domain.entities.CreditBalanceEntity.State, p: example.bankwealth.domain.invariants.params.CreditBalanceRuleParams.CommitIncomingCreditsParams): example.bankwealth.domain.values.Money = throw new UnsupportedOperationException("query-only test port")
        def BalanceAfterReleaseReservedFunds(state: example.bankwealth.domain.entities.CreditBalanceEntity.State, p: example.bankwealth.domain.invariants.params.CreditBalanceRuleParams.ReleaseReservedFundsParams): example.bankwealth.domain.values.Money = throw new UnsupportedOperationException("query-only test port")
        def BalanceAfterReserveFunds(state: example.bankwealth.domain.entities.CreditBalanceEntity.State, p: example.bankwealth.domain.invariants.params.CreditBalanceRuleParams.ReserveFundsParams): example.bankwealth.domain.values.Money = throw new UnsupportedOperationException("query-only test port")
      }
      val ref = kit.spawn(example.bankwealth.infrastructure.bootstrap.CreditBalanceBootstrap.create("generated-CreditBalance", example.bankwealth.domain.entities.CreditBalanceEntity.empty, hosts))
      val probe = kit.createTestProbe[example.bankwealth.domain.entities.CreditBalanceEntity.State]()
      ref ! example.bankwealth.application.aggregates.CreditBalanceProtocol.GetState(probe.ref)
      probe.expectMessage(example.bankwealth.domain.entities.CreditBalanceEntity.empty)
    } finally kit.shutdownTestKit()
  }
  test("bankwealth/FundOrder real actor serves typed state") {
    val kit = ActorTestKit(ConfigFactory.parseString("akka.actor.provider = local").withFallback(PersistenceTestKitPlugin.config).withFallback(ConfigFactory.load()))
    try {
      val hosts = new example.bankwealth.domain.services.FundOrderComputations {
        def StableRefundOperationId(state: example.bankwealth.domain.entities.FundOrderEntity.State, p: example.bankwealth.domain.invariants.params.FundOrderRuleParams.RequestFundPurchaseRefundParams): example.bankwealth.domain.values.OperationId = throw new UnsupportedOperationException("query-only test port")
        def StableTaRequestId(state: example.bankwealth.domain.entities.FundOrderEntity.State, p: example.bankwealth.domain.invariants.params.FundOrderRuleParams.RegisterFundTASubmissionParams): example.bankwealth.domain.values.TaRequestId = throw new UnsupportedOperationException("query-only test port")
      }
      val ref = kit.spawn(example.bankwealth.infrastructure.bootstrap.FundOrderBootstrap.create("generated-FundOrder", example.bankwealth.domain.entities.FundOrderEntity.empty, hosts, new example.bankwealth.application.aggregates.FundOrderProtocol.ExternalAuthority { def authorize(producer: String, authorization: String, identity: Vector[String]): Boolean = false }))
      val probe = kit.createTestProbe[example.bankwealth.domain.entities.FundOrderEntity.State]()
      ref ! example.bankwealth.application.aggregates.FundOrderProtocol.GetState(probe.ref)
      probe.expectMessage(example.bankwealth.domain.entities.FundOrderEntity.empty)
    } finally kit.shutdownTestKit()
  }
  test("bankwealth/SipPlan real actor serves typed state") {
    val kit = ActorTestKit(ConfigFactory.parseString("akka.actor.provider = local").withFallback(PersistenceTestKitPlugin.config).withFallback(ConfigFactory.load()))
    try {
      val hosts = new example.bankwealth.domain.services.SipPlanComputations {
        def StableSipOccurrence(state: example.bankwealth.domain.entities.SipPlanEntity.State, p: example.bankwealth.domain.invariants.params.SipPlanRuleParams.TriggerSipInstallmentParams): example.bankwealth.domain.values.SipOccurrence = throw new UnsupportedOperationException("query-only test port")
      }
      val ref = kit.spawn(example.bankwealth.infrastructure.bootstrap.SipPlanBootstrap.create("generated-SipPlan", example.bankwealth.domain.entities.SipPlanEntity.empty, hosts))
      val probe = kit.createTestProbe[example.bankwealth.domain.entities.SipPlanEntity.State]()
      ref ! example.bankwealth.application.aggregates.SipPlanProtocol.GetState(probe.ref)
      probe.expectMessage(example.bankwealth.domain.entities.SipPlanEntity.empty)
    } finally kit.shutdownTestKit()
  }
}

import org.scalatest.funsuite.AnyFunSuite

final class GeneratedDomainRoundtripSpec extends AnyFunSuite {
  example.bankwealth.service.UnitConfigurationCheck.main(Array.empty)
  test("bankwealth/CreditBalance state survives actual protobuf bytes") {
    val state = example.bankwealth.domain.CreditBalanceState.empty
    val encoded = example.bankwealth.infrastructure.serialization.DomainConverters.encodeCreditBalanceStatePO(state)
    val parsed = example.bankwealth.infrastructure.proto.CreditBalanceStatePO.parseFrom(encoded.toByteArray)
    assert(example.bankwealth.infrastructure.serialization.DomainConverters.decodeCreditBalanceStatePO(parsed) == state)
  }
  test("bankwealth/FundOrder state survives actual protobuf bytes") {
    val state = example.bankwealth.domain.FundOrderState.empty
    val encoded = example.bankwealth.infrastructure.serialization.DomainConverters.encodeFundOrderStatePO(state)
    val parsed = example.bankwealth.infrastructure.proto.FundOrderStatePO.parseFrom(encoded.toByteArray)
    assert(example.bankwealth.infrastructure.serialization.DomainConverters.decodeFundOrderStatePO(parsed) == state)
  }
  test("bankwealth/SipPlan state survives actual protobuf bytes") {
    val state = example.bankwealth.domain.SipPlanState.empty
    val encoded = example.bankwealth.infrastructure.serialization.DomainConverters.encodeSipPlanStatePO(state)
    val parsed = example.bankwealth.infrastructure.proto.SipPlanStatePO.parseFrom(encoded.toByteArray)
    assert(example.bankwealth.infrastructure.serialization.DomainConverters.decodeSipPlanStatePO(parsed) == state)
  }
  test("bankwealth/Money exact domain wire PO and protobuf roundtrip") {
    val value = example.bankwealth.domain.values.Money(BigDecimal("0.01"), "CNY")
    val c = example.bankwealth.infrastructure.serialization.DomainConverters
    assert(c.MoneyFromWire(c.MoneyToWire(value)) == value)
    assert(c.MoneyFromPO(c.MoneyToPO(value)) == value)
    val encoded = c.encodeMoneyPO(value)
    assert(c.decodeMoneyPO(example.bankwealth.infrastructure.proto.MoneyPO.parseFrom(encoded.toByteArray)) == value)
    intercept[IllegalArgumentException](c.decodeMoneyPO(encoded.copy(amount = "1e2")))
  }
  test("bankwealth/AmountDecimal exact domain wire PO and protobuf roundtrip") {
    val value = example.bankwealth.domain.values.AmountDecimal(BigDecimal("0.01"))
    val c = example.bankwealth.infrastructure.serialization.DomainConverters
    assert(c.AmountDecimalFromWire(c.AmountDecimalToWire(value)) == value)
    assert(c.AmountDecimalFromPO(c.AmountDecimalToPO(value)) == value)
    val encoded = c.encodeAmountDecimalPO(value)
    assert(c.decodeAmountDecimalPO(example.bankwealth.infrastructure.proto.AmountDecimalPO.parseFrom(encoded.toByteArray)) == value)
    intercept[IllegalArgumentException](c.decodeAmountDecimalPO(encoded.copy(value = "1e2")))
  }
}

package example.bankwealth.service

import com.typesafe.config.{Config, ConfigFactory, ConfigUtil, ConfigValueFactory}
import org.scalatest.funsuite.AnyFunSuite

final class GeneratedServiceConfigurationSpec extends AnyFunSuite {
  UnitConfigurationCheck.main(Array.empty)

  private val mongoRoot = "akka.contrib.persistence.mongodb.mongo"
  private val journalPlugin = "akka-contrib-mongodb-persistence-journal"
  private val snapshotPlugin = "akka-contrib-mongodb-persistence-snapshot"
  private val namespacePath = "bank.namespace"
  private val journalRef = "bank-mongo-connection"
  private val readSideRef = "bank-mysql-connection"
  private val mongoPath = ConfigUtil.joinPath("service", "connections", journalRef)
  private val jdbcPath = ConfigUtil.joinPath("service", "connections", readSideRef)
  private val mongo = "mongodb://127.0.0.1:1/configuration_check"
  private val jdbc = "jdbc:mysql://127.0.0.1:1/configuration_check"
  private def text(value: String) = ConfigValueFactory.fromAnyRef(value)
  // Construct only synthetic values. Do not load production configuration, factories, actors, or drivers.
  private val good = Vector(
    namespacePath -> "isolated_configuration_check",
    "play.http.secret.key" -> "configuration-test-only-not-a-secret",
    mongoPath -> mongo,
    jdbcPath -> jdbc,
    "akka.persistence.journal.plugin" -> journalPlugin,
    "akka.persistence.snapshot-store.plugin" -> snapshotPlugin,
    ConfigUtil.joinPath(journalPlugin, "class") -> "akka.contrib.persistence.mongodb.MongoJournal",
    ConfigUtil.joinPath(snapshotPlugin, "class") -> "akka.contrib.persistence.mongodb.MongoSnapshots",
    (mongoRoot + ".driver") -> "akka.contrib.persistence.mongodb.RxMongoPersistenceExtension",
    (mongoRoot + ".mongouri") -> mongo,
    (mongoRoot + ".db") -> "akka-persistence",
    "db.default.driver" -> "com.mysql.cj.jdbc.Driver",
    "db.default.url" -> jdbc
  ).foldLeft(ConfigFactory.empty()) { case (config, (path, value)) => config.withValue(path, text(value)) }
  private def checked(config: Config): Unit = BankServiceConfiguration.validate(play.api.Configuration(config))
  private def rejected(config: Config): Unit = {
    val error = intercept[IllegalArgumentException](checked(config))
    assert(error.getMessage == "invalid service configuration")
    assert(error.getCause == null)
  }
  private def withMongo(value: String): Config = good.withValue(mongoPath, text(value)).withValue(mongoRoot + ".mongouri", text(value))
  private def withJdbc(value: String): Config = good.withValue(jdbcPath, text(value)).withValue("db.default.url", text(value))

  test("explicit isolated namespace and destinations validate without driver initialization") {
    checked(good)
    // Namespace need not equal either database. The legacy mongo.db default must never supply a missing URI database.
    checked(good.withValue(namespacePath, text("another_isolated_namespace")))
  }
  test("Mongo credentials multi-host addresses and options preserve the explicit raw database") {
    for (value <- Vector(
      "mongodb://mongo-a.invalid/configuration_check?authSource=admin",
      "mongodb://mongo-a.invalid:1,mongo-b.invalid:2/configuration_check?replicaSet=test&ssl=true",
      "mongodb://fake-user:fake-pass@mongo-a.invalid:1,mongo-b.invalid:2/configuration_check?authSource=admin",
      "mongodb://fake%40user:fake%3Apass@mongo-a.invalid:1/configuration_check?authSource=admin"
    )) checked(withMongo(value))
    checked(withJdbc("jdbc:mysql://mysql.invalid:1/configuration_check?useSSL=false&serverTimezone=UTC"))
  }
  test("Mongo rejects absent invalid or encoded databases rather than selecting akka-persistence") {
    for (value <- Vector(
      "mongodb://127.0.0.1:1", "mongodb://127.0.0.1:1/", "mongodb://127.0.0.1:1?authSource=admin",
      "mongodb://127.0.0.1:1/?authSource=admin", "mongodb://127.0.0.1:1/bad.name",
      "mongodb://127.0.0.1:1/bad%2Fname", "mongodb://127.0.0.1:1/bad/name",
      "mongodb://127.0.0.1:1/bad name", "mongodb://127.0.0.1:1/" + "a" * 64,
      "mongodb+srv://mongo.invalid/configuration_check", "mongodb://127.0.0.1:0/configuration_check",
      "mongodb://127.0.0.1:65536/configuration_check", "mongodb:///configuration_check",
      "mongodb://mongo.invalid,/configuration_check", "mongodb://fake%ZZ:fake-pass@mongo.invalid/configuration_check",
      "mongodb://mongo.invalid/configuration_check?authSource", "mongodb://mongo.invalid/configuration_check#fragment"
    )) rejected(withMongo(value))
  }
  test("MySQL requires its pinned scheme explicit database and driver") {
    for (value <- Vector(
      "jdbc:mysql://127.0.0.1:1", "jdbc:mysql://127.0.0.1:1/", "jdbc:mysql://127.0.0.1:1/?useSSL=false",
      "jdbc:mysql://127.0.0.1:1/bad/name", "jdbc:mysql://127.0.0.1:1/bad%2Fname",
      "jdbc:mysql:///configuration_check", "jdbc:mysql://mysql.invalid:0/configuration_check",
      "jdbc:postgresql://127.0.0.1:1/configuration_check"
    )) rejected(withJdbc(value))
    rejected(good.withValue("db.default.driver", text("org.postgresql.Driver")))
  }
  test("all required configuration fails closed when absent before factory creation") {
    for (path <- Vector(namespacePath, "play.http.secret.key", mongoPath, jdbcPath,
      "akka.persistence.journal.plugin", "akka.persistence.snapshot-store.plugin",
      ConfigUtil.joinPath(journalPlugin, "class"), ConfigUtil.joinPath(snapshotPlugin, "class"),
      mongoRoot + ".driver", mongoRoot + ".mongouri", "db.default.driver", "db.default.url")) {
      rejected(good.withoutPath(path))
    }
  }
  test("empty default or malformed secrets yield only a generic error without a cause") {
    for (secret <- Vector("", "   ", "changeme", " CHANGEME ")) rejected(good.withValue("play.http.secret.key", text(secret)))
    rejected(good.withValue("play.http.secret.key", ConfigValueFactory.fromAnyRef(null)))
    rejected(good.withValue("play.http.secret.key", ConfigFactory.parseString("value = [test-only]").getValue("value")))
    for (namespace <- Vector("", "bad.namespace", "bad namespace", "a" * 65)) rejected(good.withValue(namespacePath, text(namespace)))
  }
  test("root database must not override the validated URI even with the same database name") {
    for (database <- Vector("configuration_check", "other_database", "")) rejected(good.withValue(mongoRoot + ".database", text(database)))
    rejected(good.withValue(mongoRoot + ".database", ConfigValueFactory.fromAnyRef(null)))
  }
  test("journal and snapshot destination overrides are rejected but tuning remains permitted") {
    for (plugin <- Vector(journalPlugin, snapshotPlugin)) {
      val overrides = ConfigUtil.joinPath(plugin, "overrides")
      for (key <- Vector("mongouri", "database", "urls", "db", "username", "password", "driver")) {
        val path = ConfigUtil.joinPath(plugin, "overrides", key)
        rejected(good.withValue(path, text(if (key == "mongouri") mongo else "test-only")))
        rejected(good.withValue(path, ConfigValueFactory.fromAnyRef(null)))
      }
      rejected(good.withValue(overrides, text("not-an-object")))
      rejected(good.withValue(overrides, ConfigValueFactory.fromAnyRef(null)))
      checked(good.withValue(overrides, ConfigFactory.parseString("journal-wtimeout = 5s").root()))
    }
  }
  test("active journal snapshot classes and RxMongo extension must match their production pins") {
    for ((path, value) <- Vector(
      "akka.persistence.journal.plugin" -> "akka.persistence.testkit.journal",
      "akka.persistence.snapshot-store.plugin" -> "akka.persistence.testkit.snapshotstore.pluginid",
      ConfigUtil.joinPath(journalPlugin, "class") -> "other.Journal",
      ConfigUtil.joinPath(snapshotPlugin, "class") -> "other.Snapshot",
      (mongoRoot + ".driver") -> "akka.contrib.persistence.mongodb.ScalaMongoPersistenceExtension"
    )) rejected(good.withValue(path, text(value)))
  }
  test("driver destinations cannot differ from the symbolic references") {
    rejected(good.withValue(mongoRoot + ".mongouri", text("mongodb://127.0.0.1:1/other_database")))
    rejected(good.withValue("db.default.url", text("jdbc:mysql://127.0.0.1:1/other_database")))
  }
  test("symbolic references containing dots remain literal connection keys rather than nested paths") {
    val literal = ConfigUtil.joinPath("service", "connections", "journal.primary")
    val example = ConfigFactory.empty().withValue(literal, text(mongo))
    assert(example.getString(literal) == mongo)
    assert(!example.hasPath("service.connections.journal.primary"))
    for ((id, path, value) <- Vector((journalRef, mongoPath, mongo), (readSideRef, jdbcPath, jdbc))) {
      assert(good.getString(ConfigUtil.joinPath("service", "connections", id)) == value)
      if (id.contains(".")) rejected(good.withoutPath(path).withValue("service.connections." + id, text(value)))
    }
  }
}

package example.bankwealth.service

import akka.actor.testkit.typed.scaladsl.ActorTestKit
import akka.persistence.typed.PersistenceId
import akka.persistence.typed.scaladsl.{Effect, EventSourcedBehavior, RetentionCriteria}
import akka.actor.typed.ActorRef
import com.typesafe.config.{ConfigFactory, ConfigResolveOptions, ConfigUtil}
import org.scalatest.funsuite.AnyFunSuite
import scala.concurrent.duration._

final class GeneratedUnitStorageSpec extends AnyFunSuite {
  UnitConfigurationCheck.main(Array.empty)
  test("service errors and strict JSON preserve client conflicts and reject ambiguous input") {
    import BankServiceService._
    assert(RequestConflict.status == 409 && NotAuthenticated.status == 401 && NotAuthorized.status == 403)
    assert(decodeBody("{\"amount\":\"10000\"}").isRight)
    for (text <- Vector("", "{} {}", "{\"a\":1,\"a\":2}", "{\"a\":{\"b\":1,\"b\":2}}", "[1,", "[" * 65 + "0" + "]" * 65)) {
      assert(decodeBody(text) == Left(InvalidRequest))
    }
  }
  test("production configuration rejects missing connections without creating actors or drivers") {
    val production = ConfigFactory.parseResources("service.conf")
    val references = ConfigFactory.parseString("""PLAY_SECRET = "test-only-not-a-secret"
MONGO_URI = "mongodb://127.0.0.1:1/never-connected"
MYSQL_JDBC_URL = "jdbc:mysql://127.0.0.1:1/never_connected"
MYSQL_USER = "test-only"
MYSQL_PASSWORD = "test-only-not-a-secret"
""")
    val isolated = ConfigResolveOptions.noSystem().setUseSystemEnvironment(false)
    for (missing <- Vector("MONGO_URI", "MYSQL_JDBC_URL", "MYSQL_USER", "MYSQL_PASSWORD", "PLAY_SECRET")) {
      intercept[com.typesafe.config.ConfigException.UnresolvedSubstitution] {
        production.withFallback(references.withoutPath(missing)).resolve(isolated)
      }
    }
    val resolved = production.withFallback(references).resolve(isolated)
    assert(resolved.getString("akka.contrib.persistence.mongodb.mongo.mongouri") == resolved.getString(ConfigUtil.joinPath("service", "connections", "bank-mongo-connection")))
    assert(resolved.getString("db.default.url") == resolved.getString(ConfigUtil.joinPath("service", "connections", "bank-mysql-connection")))
  }
  test("unit configuration denies production stores and socket access before actors start") {
    val config = ConfigFactory.load()
    UnitConfigurationCheck.validate(config)
    for (overrideText <- Vector(
      "akka.persistence.journal.plugin = akka-contrib-mongodb-persistence-journal",
      "akka.persistence.snapshot-store.plugin = akka-contrib-mongodb-persistence-snapshot",
      "akka.persistence.snapshot-store.auto-start-snapshot-stores = [akka-contrib-mongodb-persistence-snapshot]",
      "akka.actor.provider = cluster",
      "db.default.url = \"jdbc:mysql://localhost/unit-forbidden\""
    )) intercept[IllegalArgumentException](UnitConfigurationCheck.validate(ConfigFactory.parseString(overrideText).withFallback(config)))
    intercept[SecurityException](new java.net.Socket("127.0.0.1", 27017))
    intercept[SecurityException](new java.net.ServerSocket(0))
  }
  test("testkit persists a real snapshot and restores the event-sourced actor without Docker") {
    val config = ConfigFactory.load()
    UnitConfigurationCheck.validate(config)
    val kit = ActorTestKit(config)
    sealed trait Command
    final case class Append(value: String, reply: ActorRef[String]) extends Command
    final case class Get(reply: ActorRef[String]) extends Command
    def behavior = EventSourcedBehavior[Command, String, String](PersistenceId.ofUniqueId("generated-unit-snapshot"), "",
      (state, command) => command match {
        case Append(value, reply) => Effect.persist(value).thenReply(reply)(identity)
        case Get(reply) => Effect.reply(reply)(state)
      }, (_, event) => event).withRetention(RetentionCriteria.snapshotEvery(numberOfEvents = 1, keepNSnapshots = 1))
    try {
      val snapshots = akka.persistence.testkit.scaladsl.SnapshotTestKit(kit.system)
      val probe = kit.createTestProbe[String]()
      val first = kit.spawn(behavior)
      first ! Append("persisted", probe.ref)
      probe.expectMessage("persisted")
      snapshots.expectNextPersisted("generated-unit-snapshot", "persisted")
      kit.stop(first)
      val recovered = kit.spawn(EventSourcedBehavior[Command, String, String](PersistenceId.ofUniqueId("generated-unit-snapshot"), "",
        (state, command) => command match {
          case Get(reply) => Effect.reply(reply)(state)
          case Append(value, reply) => Effect.persist(value).thenReply(reply)(identity)
        }, (_, event) => event))
      recovered ! Get(probe.ref)
      probe.expectMessage("persisted")
    } finally kit.shutdownTestKit()
  }
}

package example.bankwealth.service

import com.typesafe.config.{Config, ConfigFactory}
import java.security.Permission
import scala.jdk.CollectionConverters._

final class UnitNoNetwork extends SecurityManager {
  override def checkPermission(permission: Permission): Unit = ()
  override def checkPermission(permission: Permission, context: Any): Unit = ()
  override def checkConnect(host: String, port: Int): Unit = throw new SecurityException("unit tests cannot connect to network services")
  override def checkConnect(host: String, port: Int, context: Any): Unit = checkConnect(host, port)
  override def checkListen(port: Int): Unit = throw new SecurityException("unit tests cannot bind network listeners")
  override def checkAccept(host: String, port: Int): Unit = throw new SecurityException("unit tests cannot accept network connections")
}
object UnitConfigurationCheck {
  def install(): Unit = {
    if (System.getSecurityManager == null) System.setSecurityManager(new UnitNoNetwork)
    require(System.getSecurityManager.isInstanceOf[UnitNoNetwork], "unit network boundary is unavailable")
  }
  def validate(config: Config): Unit = {
    require(config.getString("service.test-tier") == "unit", "explicit unit tier required")
    require(config.getString("akka.actor.provider") == "local", "unit actor provider must be local")
    require(config.getString("akka.persistence.journal.plugin") == "akka.persistence.testkit.journal", "unit journal must be testkit")
    require(config.getString("akka.persistence.snapshot-store.plugin") == "akka.persistence.testkit.snapshotstore.pluginid", "unit snapshot store must be testkit")
    require(config.getString("akka.persistence.testkit.journal.class") == "akka.persistence.testkit.PersistenceTestKitPlugin", "unit journal implementation must be testkit")
    require(config.getString("akka.persistence.testkit.snapshotstore.pluginid.class") == "akka.persistence.testkit.PersistenceTestKitSnapshotPlugin", "unit snapshot implementation must be testkit")
    require(config.getStringList("akka.persistence.journal.auto-start-journals").isEmpty, "unit journal auto-start must be empty")
    require(config.getStringList("akka.persistence.snapshot-store.auto-start-snapshot-stores").isEmpty, "unit snapshot auto-start must be empty")
    require(config.getString("play.application.loader").isEmpty && !config.hasPath("service.connections"), "unit configuration must not include production service wiring")
    require(!config.hasPath("db") || config.getConfig("db").root().isEmpty, "unit configuration must not enable JDBC pools")
    require(System.getSecurityManager.isInstanceOf[UnitNoNetwork], "unit JVM must enforce no-network execution")
  }
  def main(args: Array[String]): Unit = {
    install()
    validate(ConfigFactory.load())
    println("UNIT-CONFIGURATION-OK journal=testkit snapshot=testkit network=denied")
  }
}
object UnitTestMain {
  def main(args: Array[String]): Unit = {
    UnitConfigurationCheck.main(Array.empty)
    println("UNIT-JVM-PID=" + ProcessHandle.current().pid())
    val suites = System.getProperty("service.test.suites", "").split(",").filter(_.nonEmpty)
    require(suites.nonEmpty && suites.exists(_.endsWith("GeneratedUnitStorageSpec")), "nonempty discovered unit suites required")
    val passed = org.scalatest.tools.Runner.run(Array("-o") ++ suites.flatMap(name => Array("-s", name)))
    require(passed, "unit suite failure")
  }
}
